<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query'
import type { ContractRegisterResult, RegisterContract } from '~~/shared/types/contract-register'
import ContractRegisterDetail from './ContractRegisterDetail.vue'
const auth=useAuthStore(),access=useProjectAccess()
const {query:companies}=useProjectCompanies()
const companyOptions=(own:boolean)=>[{label:'Все',value:'all'},...(companies.data.value||[]).filter(row=>row.isOwnLegalEntity===own).map(row=>({label:row.company,value:row.id,inn:row.inn,description:row.inn?'ИНН '+row.inn:''}))]
const q=ref(''),search=ref(''),page=ref(1),editing=ref(false),selected=ref<RegisterContract|null>(null)
const filters=reactive({legalEntityId:'all',counterpartyId:'all',origin:'all',projectId:'all',source:'all',status:'all',from:'',until:'',files:'all',sort:'date-desc',pageSize:'25'})
let timer:ReturnType<typeof setTimeout>|undefined
watch(q,value=>{clearTimeout(timer);timer=setTimeout(()=>{search.value=value;page.value=1},300)})
onBeforeUnmount(()=>clearTimeout(timer))
watch(()=>filters.origin,value=>{if(value==='standalone')filters.projectId='all'})
watch(()=>({...filters}),()=>{page.value=1})
const params=computed(()=>new URLSearchParams({...filters,q:search.value,page:String(page.value)}).toString())
const query=useQuery({queryKey:computed(()=>['account',auth.user?.id,'contract-register',params.value]),queryFn:({signal})=>sharedRequest<ContractRegisterResult>(`/api/contract-register?${params.value}`,{signal}),enabled:computed(()=>!!auth.user&&!!access.data.value?.allowed),retry:false,refetchInterval:30000})
watch(()=>auth.user?.id,()=>{editing.value=false;selected.value=null;reset()})
watch(()=>access.data.value?.allowed,allowed=>{if(!allowed){editing.value=false;selected.value=null}})
function reset(){clearTimeout(timer);q.value='';search.value='';page.value=1;Object.assign(filters,{legalEntityId:'all',counterpartyId:'all',origin:'all',projectId:'all',source:'all',status:'all',from:'',until:'',files:'all',sort:'date-desc',pageSize:'25'})}
const columns=[{key:'number',label:'Номер'},{key:'project',label:'Проект / источник'},{key:'seller',label:'Продавец / исполнитель'},{key:'buyer',label:'Покупатель / заказчик'},{key:'date',label:'Дата'},{key:'deadline',label:'Срок'},{key:'amount',label:'Сумма с НДС, ₽'},{key:'vat',label:'НДС, ₽'},{key:'files',label:'Файлы'}]
function sortBy(key:string){filters.sort=filters.sort===key+'-asc'?key+'-desc':key+'-asc'}
function sortState(key:string){return filters.sort===key+'-asc'?'ascending':filters.sort===key+'-desc'?'descending':'none'}
watch(()=>query.data.value,data=>{if(data&&data.page!==page.value)page.value=data.page})
function open(row:RegisterContract|null){selected.value=row;editing.value=true}
const money=(value:number|null)=>value===null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(value)
const date=(value:string)=>value?value.split('-').reverse().join('.'):'—'
</script>
<template>
 <section class="registry" aria-label="Общий реестр договоров">
  <header class="registry-intro"><p>Договоры этапа «Договора» отображаются автоматически и обновляются вместе со сметой. Здесь же можно добавить договор и файлы без привязки к проекту.</p><UButton label="Добавить договор" icon="i-lucide-plus" @click="open(null)"/></header>
  <div class="registry-filters">
   <UFormField label="Поиск" class="registry-search"><UInput v-model="q" icon="i-lucide-search" placeholder="Номер, стороны или проект" :maxlength="300" class="w-full"/></UFormField>
   <UFormField label="Наше юр. лицо"><USelectMenu v-model="filters.legalEntityId" :items="companyOptions(true)" value-key="value" :filter-fields="['label','inn']" :search-input="{placeholder:'Название или ИНН'}" class="w-full" :loading="companies.isPending.value"><template #empty>Юр. лица не найдены</template></USelectMenu></UFormField>
   <UFormField label="Контрагент"><USelectMenu v-model="filters.counterpartyId" :items="companyOptions(false)" value-key="value" :filter-fields="['label','inn']" :search-input="{placeholder:'Название или ИНН'}" class="w-full" :loading="companies.isPending.value"><template #empty>Контрагенты не найдены</template></USelectMenu></UFormField>
   <UFormField label="Источник"><USelect v-model="filters.origin" :items="[{label:'Все договоры',value:'all'},{label:'Из проектов',value:'project'},{label:'Без проекта',value:'standalone'}]" class="w-full"/></UFormField>
   <UFormField label="Проект"><USelectMenu v-model="filters.projectId" value-key="value" :search-input="{placeholder:'Найти проект…'}" aria-label="Проект" :items="[{label:'Все проекты',value:'all'},...(query.data.value?.projects.map(p=>({label:p.name,value:p.id}))||[])]" class="w-full" :disabled="filters.origin==='standalone'"><template #empty>Проекты не найдены</template></USelectMenu></UFormField>
   <UFormField label="Тип"><USelect v-model="filters.source" :items="[{label:'Все типы',value:'all'},{label:'Выручка сметы',value:'revenue'},{label:'Затраты сметы',value:'expenses'},{label:'Добавленные вручную',value:'manual'}]" class="w-full"/></UFormField>
   <UFormField label="Срок"><USelect v-model="filters.status" :items="[{label:'Любой срок',value:'all'},{label:'Срок прошёл',value:'overdue'},{label:'Сегодня или позже',value:'upcoming'},{label:'Без срока',value:'no-deadline'},{label:'Автопродление',value:'auto-renew'}]" class="w-full"/></UFormField>
   <UFormField label="Дата договора от"><UInput v-model="filters.from" type="date" class="w-full"/></UFormField>
   <UFormField label="Дата договора до"><UInput v-model="filters.until" type="date" class="w-full"/></UFormField>
   <UFormField label="Вложения"><USelect v-model="filters.files" :items="[{label:'Любые',value:'all'},{label:'Есть файлы',value:'yes'},{label:'Без файлов',value:'no'}]" class="w-full"/></UFormField>
   <UFormField label="На странице"><USelect v-model="filters.pageSize" :items="[{label:'10',value:'10'},{label:'25',value:'25'},{label:'50',value:'50'},{label:'100',value:'100'}]" class="w-full"/></UFormField>
  </div>
  <div class="registry-summary"><span role="status">{{ query.isPending.value ? 'Загружаем договоры…' : `Найдено договоров: ${query.data.value?.total ?? 0}` }}</span><div><UButton label="Сбросить фильтры" color="neutral" variant="ghost" @click="reset"/><UButton label="Обновить" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="query.isFetching.value" @click="query.refetch()"/></div></div>
  <UAlert v-if="companies.error.value" color="error" title="Не удалось загрузить компании для фильтров" :actions="[{label:'Повторить',onClick:()=>companies.refetch()}]"/>
  <UAlert v-if="query.error.value" color="error" :description="(query.error.value as any)?.data?.message || 'Не удалось загрузить реестр договоров.'"/>
  <div v-else-if="query.data.value?.contracts.length" class="registry-table-wrap"><table class="registry-table"><colgroup><col v-for="(width,index) in [11,12,15,15,9,9,11,11,7]" :key="index" :style="{width:width+'%'}"/></colgroup><thead><tr><th v-for="column in columns" :key="column.key" :aria-sort="sortState(column.key)"><button type="button" class="inline-flex items-center gap-2 text-left" @click="sortBy(column.key)">{{column.label}}<UIcon :name="sortState(column.key)==='ascending'?'i-lucide-arrow-up':sortState(column.key)==='descending'?'i-lucide-arrow-down':'i-lucide-arrow-up-down'" class="shrink-0"/></button></th></tr></thead><tbody><tr v-for="row in query.data.value.contracts" :key="row.origin+row.id"><td><button class="registry-contract-link" @click="open(row)">{{ row.number }}</button><small v-if="row.issue" class="registry-issue">Требует проверки</small></td><td><span>{{ row.projectName || 'Без проекта' }}</span><small>{{ row.source==='revenue'?'Выручка сметы':row.source==='expenses'?'Затраты сметы':'Добавлен вручную' }}</small></td><td>{{ row.seller || '—' }}</td><td>{{ row.buyer || '—' }}</td><td class="registry-nowrap">{{ date(row.date) }}</td><td class="registry-nowrap">{{ row.noDeadline?'Без срока':date(row.deadline) }}<small v-if="row.autoRenew">Автопродление</small></td><td class="registry-nowrap">{{ money(row.amount) }}</td><td class="registry-nowrap">{{ money(row.vatAmount) }}</td><td><UButton :label="row.fileCount?String(row.fileCount):undefined" :icon="row.fileCount?'i-lucide-paperclip':'i-lucide-eye'" color="neutral" variant="ghost" :title="`Открыть договор ${row.number}, файлов: ${row.fileCount}`" :aria-label="`Открыть договор ${row.number}, файлов: ${row.fileCount}`" @click="open(row)"/></td></tr></tbody></table></div>
  <div v-else-if="!query.isPending.value && !query.error.value" class="registry-empty"><UIcon name="i-lucide-notebook-tabs"/><h2>Договоры не найдены</h2><p>Измените фильтры или добавьте договор без проекта. Договоры из проектов появятся здесь автоматически.</p></div>
  <footer v-if="query.data.value" class="registry-pagination flex-wrap"><span>Страница {{query.data.value.page}} из {{query.data.value.pages}} · Всего {{query.data.value.total}}</span><UPagination v-model:page="page" :total="query.data.value.total" :items-per-page="query.data.value.pageSize" :disabled="query.isFetching.value" :sibling-count="1" show-edges/></footer>
  <ContractRegisterDetail v-if="editing" :contract="selected" @close="editing=false; selected=null" @changed="query.refetch()"/>
 </section>
</template>
<style scoped>
.registry{display:grid;gap:22px;min-width:0}.registry-intro{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.registry-intro p{max-width:750px;font-size:13px;line-height:1.9;color:#8292a8}.registry-intro>button{flex-shrink:0}.registry-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:20px;border:1px solid #e2e8f0;border-radius:16px;background:#fff}.registry-search{grid-column:span 2}.registry-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;color:#8292a8}.registry-summary>div{display:flex;gap:8px;flex-wrap:wrap}.registry-table-wrap{overflow-x:auto;border:1px solid #e2e8f0;border-radius:16px;background:#fff}.registry-table{width:100%;min-width:1120px;border-collapse:collapse;text-align:left;font-size:12px;color:#475569}.registry-table th{background:#f8fafc;color:#8292a8;font-weight:600;font-size:11px;white-space:nowrap}.registry-table td,.registry-table th{padding:18px 16px;border-bottom:1px solid #edf2f7;vertical-align:top}.registry-table tbody tr:last-child td{border-bottom:0}.registry-table small{display:block;margin-top:5px;font-size:10px;color:#94a3b8}.registry-contract-link{font-weight:650;text-align:left;overflow-wrap:anywhere;color:var(--ui-primary)}.registry-contract-link:hover{text-decoration:underline}.registry-nowrap{white-space:nowrap}.registry-table .registry-issue{color:#b45309}.registry-empty{text-align:center;padding:55px 20px;border:1px dashed #dbe3ee;border-radius:16px;color:#8292a8}.registry-empty>.iconify{font-size:32px}.registry-empty h2{font-size:19px;color:#475569;font-weight:600;margin:16px 0 10px}.registry-empty p{max-width:420px;margin:auto;font-size:13px;line-height:1.8}.registry-pagination{display:flex;align-items:center;justify-content:center;gap:20px;font-size:12px;color:#8292a8}@media(max-width:900px){.registry-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.registry-intro{flex-direction:column;gap:14px}.registry-intro>button{width:100%;justify-content:center}.registry-filters{padding:16px;gap:12px;grid-template-columns:minmax(0,1fr)}.registry-search{grid-column:auto}.registry-summary{align-items:flex-start;flex-direction:column}}
.registry-table{table-layout:fixed;min-width:0;font-size:12px}.registry-table th{white-space:normal;overflow-wrap:anywhere;line-height:1.5}.registry-table td,.registry-table th{padding:16px 10px}.registry-table td{overflow-wrap:anywhere}.registry-table th button{max-width:100%;gap:5px;align-items:flex-start}.registry-table th button>.iconify{margin-top:2px;width:12px;height:12px}.registry-table small{overflow-wrap:anywhere}.registry-table .registry-nowrap{font-variant-numeric:tabular-nums;font-size:11px}@media(max-width:1399px){.registry-table{min-width:1000px}}
</style>
